function hidden(string $action,int $id=0):void{echo '<input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><input type="hidden" name="action" value="'.h($action).'"><input type="hidden" name="id" value="'.$id.'">';}
function input(string $name,string $label,mixed $value='',string $type='text',bool $required=true):void{echo '<label>'.h($label).'<input name="'.h($name).'" type="'.h($type).'" value="'.h($value).'" '.($required?'required':'').($type==='number'?' min="0" step="1"':'').'></label>';}
function check(string $name,string $label,bool $value=false):void{echo '<label class="check"><input type="checkbox" name="'.h($name).'" '.($value?'checked':'').'>'.h($label).'</label>';}
function select(string $name,string $label,array $options,mixed $selected=null,string $extra=''):void{echo '<label>'.h($label).'<select name="'.h($name).'" required '.$extra.'>';foreach($options as $id=>$title)echo '<option value="'.h($id).'" '.((string)$selected===(string)$id?'selected':'').'>'.h($title).'</option>';echo '</select></label>';}
function options(array $rows,string $label='name'):array{$r=[];foreach($rows as $x)$r[$x['id']]=$x[$label];return $r;}
function badge(string $status):void{echo '<span class="badge '.h($status).'">'.h(ucwords(str_replace('_',' ',$status))).'</span>';}
function emptyState(string $text):void{echo '<div class="empty"><span>✧</span><p>'.h($text).'</p></div>';}
function submit(string $text='Save'):void{echo '<button type="submit" class="btn">'.h($text).' <span>↗</span></button>';}
function locationOptions(bool $activeOnly=false):array{[$s,$a]=scope('id');return options(all('SELECT * FROM locations WHERE '.$s.($activeOnly?' AND active=1':'').' ORDER BY name',$a));}
function editRecord(string $table):?array{$id=filter_var($_GET['edit']??0,FILTER_VALIDATE_INT);return $id?row("SELECT * FROM $table WHERE id=?",[$id]):null;}
function dateFilters():array{$from=validDate((string)($_GET['from']??date('Y-m-01')));$to=validDate((string)($_GET['to']??date('Y-m-d')));if($from>$to)fail('Start date must be before end date.');return [$from,$to];}
