$jobs=all("SELECT w.*,b.registration,c.name AS customer,l.name AS location,u.name AS washer FROM washes w JOIN bikes b ON b.id=w.bike_id JOIN customers c ON c.id=b.customer_id JOIN locations l ON l.id=w.location_id JOIN users u ON u.id=w.washer_id WHERE $s $extra ORDER BY w.id DESC LIMIT 200",$a);?>
<div class="page-title"><div><p class="eyebrow">THE DAILY FLOW</p><h1>From dusty to done.</h1><p>Queue → Washing → Quality check → Completed.</p></div><a class="btn" href="#new">＋ Start a wash</a></div><section class="panel"><div class="panel-head"><h2>Wash queue & history</h2><form method="get" class="inline"><input type="hidden" name="page" value="washes"><input class="search" name="bike" placeholder="Enter bike number" value="<?=h($query)?>"><button class="btn secondary">Find</button></form></div><div class="table-wrap"><table><thead><tr><th>Bike / rider</th><th>Location / washer</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($jobs as $w):?><tr><td><strong><?=h($w['registration'])?></strong><small><?=h($w['customer'])?> · #<?=$w['id']?></small><small><?=h($w['created_at'])?></small></td><td><?=h($w['location'])?><small><?=h($w['washer'])?></small></td><td><?php badge($w['status']);?><?php if($w['note']):?><small><?=h($w['note'])?></small><?php endif?></td><td><?php $next=match($w['status']){'queued'=>['washing'=>'Begin washing','cancelled'=>'Cancel'],'washing'=>['quality'=>'Send for quality check','cancelled'=>'Cancel'],'quality'=>['completed'=>'Approve completion','washing'=>'Request rewash','cancelled'=>'Cancel'],default=>[]};if($next&&in_array($u['role'],['admin','partner','supervisor','captain','washer'],true)):?><form class="job-action" method="post"><?php hidden('wash_status',(int)$w['id']);select('status','Next step',$next);input('note','Note / rewash reason','','text',false);submit('Update');?></form><?php endif?></td></tr><?php endforeach?></tbody></table><?php if(!$jobs)emptyState('No washes found. Your next fresh start begins below.');?></div></section>
