// Intake may redeem packages sold elsewhere. Search requires an exact plate to avoid exposing the full cross-location directory.
$exact='';try{if($query!=='')$exact=plate($query);}catch(Throwable $e){}
$bike=$exact?row('SELECT b.*,c.name AS owner FROM bikes b JOIN customers c ON c.id=b.customer_id WHERE b.registration=?',[$exact]):null;
?><section class="panel form-panel" id="new"><h2>New wash · enter the bike number above</h2><?php if($bike):?><p class="intake-bike"><span class="plate"><?=h($bike['registration'])?></span> <?=h($bike['owner'])?></p><form method="post" class="form-grid"><?php hidden('wash_create');?><input type="hidden" name="bike_id" value="<?=$bike['id']?>"><?php $opts=[];foreach(all("SELECT m.* FROM memberships m JOIN membership_bikes mb ON mb.membership_id=m.id WHERE mb.bike_id=? AND m.status='active' AND m.expires_at>=? AND m.remaining>m.reserved",[$bike['id'],date('Y-m-d')]) as $m)$opts[$m['id']]='#'.$m['id'].' '.$m['package_name'].' · '.($m['remaining']-$m['reserved']).' available';select('membership_id','Available membership',$opts);select('location_id','Washing location',locationOptions(true));[$ws,$wa]=scope('ul.location_id');$staff=all("SELECT DISTINCT u.id,u.name FROM users u JOIN user_locations ul ON ul.user_id=u.id WHERE $ws AND u.active=1 AND u.role IN ('captain','washer') ORDER BY u.name",$wa);select('washer_id','Assigned washer',options($staff));submit('Reserve & queue wash');?></form><?php else:?><p>Search an exact registration number, for example PB10AB1234. New customers must first be registered with a paid package.</p><?php endif?></section><?php endif?>
