<div class="page-title"><div><p class="eyebrow">CASHLESS BY DESIGN</p><h1>Scan. Pay. Shine.</h1><p>Packages activate only after verified payment. No cash entry is available.</p></div></div><div class="payment-grid"><?php foreach($payments as $p):?><article class="panel payment-card"><div class="panel-head"><h2>#<?=$p['id']?> · <?=h($p['customer'])?></h2><?php badge($p['status']);?></div><div class="payment-amount"><?=money((int)$p['amount_paise'])?></div><p><?=h($p['package_name'])?><small><?=h($p['location'])?> · <?=h($p['provider'])?></small></p><?php if($p['qr_url']&&$p['status']==='pending'):?><img class="payment-qr" src="<?=h($p['qr_url'])?>" alt="Scan with your UPI app to pay <?=h(money((int)$p['amount_paise']))?>"><p class="small">Refresh after payment. Activation follows the verified payment notification.</p><?php endif?><?php if($p['status']==='pending'&&!$p['qr_id']):?><form method="post"><?php hidden(demo()?'payment_demo':'payment_qr',(int)$p['id']);submit(demo()?'Simulate payment — DEMO':'Generate UPI QR');?></form><?php endif?><?php if($p['status']==='paid'):?><p class="receipt">Reference: <?=h($p['provider_payment_id'])?><br>Paid: <?=h($p['paid_at'])?></p><?php endif?><?php if($p['status']==='qr_creating'&&$admin):?><p class="alert">QR creation needs reconciliation. Verify the merchant dashboard; do not collect payment twice.</p><form method="post"><?php hidden('payment_reconcile',(int)$p['id']);input('qr_id','Existing merchant QR reference');submit('Verify & restore QR');?></form><?php endif?></article><?php endforeach?></div><?php if(!$payments)emptyState('Create a customer package purchase to collect your first payment.');?>
<?php elseif($page==='finance'):
try{[$from,$to]=dateFilters();}catch(Throwable $e){$from=date('Y-m-01');$to=date('Y-m-d');echo '<p class="alert error">Invalid date range; showing current month.</p>';}
[$s,$a]=scope('location_id');$filterLoc=(int)($_GET['location_id']??0);if($filterLoc){try{locationAccess($filterLoc);$s.=' AND location_id=?';$a[]=$filterLoc;}catch(Throwable $e){$filterLoc=0;}}
$start=$from.' 00:00:00';$end=date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00';
$collection=(int)scalar("SELECT COALESCE(SUM(amount_paise),0) FROM payments WHERE $s AND status='paid' AND paid_at>=? AND paid_at<?",[...$a,$start,$end]);
$earned=(int)scalar("SELECT COALESCE(SUM(earned_paise),0) FROM washes WHERE $s AND status='completed' AND completed_at>=? AND completed_at<?",[...$a,$start,$end]);
$cost=(int)scalar("SELECT COALESCE(SUM(amount_paise),0) FROM expenses WHERE $s AND spent_on>=? AND spent_on<=?",[...$a,$from,$to]);
$prepaid=(int)scalar("SELECT COALESCE(SUM(amount_paise),0) FROM payments WHERE $s AND status='paid'",$a)-(int)scalar("SELECT COALESCE(SUM(earned_paise),0) FROM washes WHERE $s AND status='completed'",$a);
?>
<div class="page-title"><div><p class="eyebrow">KNOW YOUR NUMBERS</p><h1>Clarity, down to the last wash.</h1><p>Cash collections and earned service revenue, shown separately.</p></div></div><form method="get" class="filter-bar"><input type="hidden" name="page" value="finance"><?php input('from','From',$from,'date');input('to','To',$to,'date');select('location_id','Location',[0=>'All assigned locations']+locationOptions(),$filterLoc);submit('Apply');?></form><div class="cards stats"><article class="card"><p>Collections</p><h2><?=money($collection)?></h2><small>Money received in selected period</small></article><article class="card"><p>Earned revenue</p><h2><?=money($earned)?></h2><small>Allocated to completed washes</small></article><article class="card"><p>Recorded expenses</p><h2><?=money($cost)?></h2><small>Includes entered payroll & operating costs</small></article><article class="card accent-card"><p>Operating <?=($earned-$cost)<0?'loss':'profit'?></p><h2><?=money($earned-$cost)?></h2><small>Earned revenue minus recorded costs</small></article></div><p class="note">Unused prepaid balance, all time: <b><?=money($prepaid)?></b>. Includes expired unused credits until an authorised accounting adjustment. This is an operational report; taxes, refunds, depreciation and accrual adjustments are not implemented.</p>
<section class="panel"><div class="panel-head"><h2>Location performance</h2></div><div class="table-wrap"><table><thead><tr><th>Location</th><th>Collections</th><th>Earned revenue</th><th>Expenses</th><th>Operating result</th></tr></thead><tbody><?php foreach(locationOptions() as $lid=>$lname){if($filterLoc&&$filterLoc!==$lid)continue;$lc=(int)scalar("SELECT COALESCE(SUM(amount_paise),0) FROM payments WHERE location_id=? AND status='paid' AND paid_at>=? AND paid_at<?",[$lid,$start,$end]);$le=(int)scalar("SELECT COALESCE(SUM(earned_paise),0) FROM washes WHERE location_id=? AND status='completed' AND completed_at>=? AND completed_at<?",[$lid,$start,$end]);$lx=(int)scalar('SELECT COALESCE(SUM(amount_paise),0) FROM expenses WHERE location_id=? AND spent_on>=? AND spent_on<=?',[$lid,$from,$to]);?><tr><td><?=h($lname)?></td><td><?=money($lc)?></td><td><?=money($le)?></td><td><?=money($lx)?></td><td><b><?=money($le-$lx)?></b></td></tr><?php }?></tbody></table></div></section><div class="two-col"><section class="panel form-panel"><h2>Record an expense</h2><form method="post"><?php hidden('expense_save');select('location_id','Location',locationOptions());select('category','Category',array_combine(['Payroll','Rent','Water','Electricity','Consumables','Repairs','Payment fees','Other'],['Payroll','Rent','Water','Electricity','Consumables','Repairs','Payment fees','Other']));input('amount','Amount (₹)');input('spent_on','Expense date',date('Y-m-d'),'date');input('note','Description','','text',false);submit('Record expense');?></form></section><section class="panel"><div class="panel-head"><h2>Expense ledger</h2></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Category / note</th><th>Amount</th></tr></thead><tbody><?php foreach(all("SELECT * FROM expenses WHERE $s AND spent_on>=? AND spent_on<=? ORDER BY spent_on DESC,id DESC LIMIT 100",[...$a,$from,$to]) as $r):?><tr><td><?=h($r['spent_on'])?></td><td><?=h($r['category'])?><small><?=h($r['note'])?></small></td><td><?=money((int)$r['amount_paise'])?></td></tr><?php endforeach?></tbody></table></div></section></div>
